package messaging

import (
	"net/url"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	messagingpb "github.com/code-payments/flipcash2-protobuf-api/generated/go/messaging/v1"
)

// Link previews (messagingpb.LinkPreview) are generated by the sending device,
// which fetches the page; the server never does. So the server cannot say
// whether a preview's title, description or image describe the page, and
// does not try to: they are the sender's claim, and the client shows the
// link's host beside them (see the proto). What the server does guarantee,
// here, is that the link a preview claims is one the recipient can read in
// the text, as a whole link, so a card can never describe a link the message
// does not carry, or a trusted-looking prefix or suffix of one it does. The
// rest is shape: a sendable URL, visible text, a well-formed image reference
// (whose ownership and readiness are checked when it is shared into the chat,
// like any media; see shareMessageMedia).
//
// The rules are the proto's, stated on LinkPreview.url, and a client applies
// the same ones before sending (and, inside encrypted content, after
// decrypting, where the server cannot). Nothing is normalized: a link that is
// not in the text exactly as the preview spells it is refused, never fixed.

// validLinkPreviews reports whether text's link previews are ones a client may
// author: each valid on its own (see validLinkPreview) and no two for the same
// link. A text with no previews is trivially valid. The count is the proto's
// to cap.
func validLinkPreviews(text *messagingpb.TextContent) bool {
	previews := text.GetLinkPreviews()
	if len(previews) == 0 {
		return true
	}
	seen := make(map[string]struct{}, len(previews))
	for _, p := range previews {
		if !validLinkPreview(text.GetText(), p) {
			return false
		}
		if _, dup := seen[p.GetUrl()]; dup {
			return false
		}
		seen[p.GetUrl()] = struct{}{}
	}
	return true
}

// validLinkPreview reports whether p is a preview a client may attach to text:
// its url is sendable (see validLinkURL) and a whole link in text (see
// linkInText), its title and any description are visible text (see
// visibleText), its title is one line (see singleLine), and its image, if any,
// is the single ORIGINAL a client may reference (see validClientMediaItem).
func validLinkPreview(text string, p *messagingpb.LinkPreview) bool {
	if p == nil {
		return false
	}
	if !validLinkURL(p.GetUrl()) || !linkInText(text, p.GetUrl()) {
		return false
	}
	if !visibleText(p.GetTitle()) || !singleLine(p.GetTitle()) {
		return false
	}
	if p.GetDescription() != "" && !visibleText(p.GetDescription()) {
		return false
	}
	if p.GetImage() != nil && !validClientMediaItem(p.GetImage()) {
		return false
	}
	return true
}

// validLinkURL reports whether link is a URL a preview may describe: an
// absolute http or https URL whose host is a plain domain name, so that the
// host a client shows is the one a browser will resolve, whichever URL parser
// each uses. Specifically it refuses:
//
//   - any scheme but http or https, and a URL with no host
//   - userinfo ("https://bank.example@evil.example/"), the classic spoof of a
//     host the eye reads first
//   - a host that is not dot-separated labels of ASCII letters, digits and
//     hyphens, with no empty label but an optional trailing dot: no IPv6
//     literal, no percent-escape, no punctuation that one parser takes as
//     part of the host and another as its end, and no non-ASCII (a client
//     sends the punycode form, so a homograph is at least visible as its
//     "xn--" label)
//   - a host whose last label is a number (all digits, or 0x and hex
//     digits), which a browser reads as an IPv4 address, in any of its
//     forms ("127.0.0.1", "127.1", "2130706433", "0x7f.1"); no page worth
//     previewing lives at an address
//   - a port that is empty or outside 1–65535
//   - whitespace anywhere, since a link in text ends at whitespace (see
//     linkInText), and so no URL holding one is ever a whole link
//   - a bidirectional control anywhere (unicode.Bidi_Control), which a
//     browser would percent-encode and which can make the link read in a
//     different order than it resolves
//
// Length is the proto's to bound. Nothing is normalized: the URL is judged
// as spelled.
func validLinkURL(link string) bool {
	if link == "" {
		return false
	}
	for _, r := range link {
		if unicode.IsSpace(r) || unicode.Is(unicode.Bidi_Control, r) {
			return false
		}
	}
	u, err := url.Parse(link)
	if err != nil {
		return false
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return false
	}
	if u.User != nil || u.Host == "" {
		return false
	}
	host := u.Hostname()
	if !validLinkHost(host) {
		return false
	}
	// With brackets refused by validLinkHost, the host is a prefix of
	// u.Host and whatever follows it is the port.
	if port := u.Host[len(host):]; port != "" {
		n, err := strconv.Atoi(strings.TrimPrefix(port, ":"))
		if !strings.HasPrefix(port, ":") || err != nil || n < 1 || n > 65535 {
			return false
		}
	}
	return true
}

// validLinkHost reports whether host is a domain name a link may name (see
// validLinkURL): dot-separated labels of ASCII letters, digits and hyphens,
// none empty, with an optional trailing dot, the last of which is not a
// number.
func validLinkHost(host string) bool {
	labels := strings.Split(strings.TrimSuffix(host, "."), ".")
	for _, label := range labels {
		if label == "" {
			return false
		}
		for i := 0; i < len(label); i++ {
			c := label[i]
			if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '-') {
				return false
			}
		}
	}
	return !numericLabel(labels[len(labels)-1])
}

// numericLabel reports whether label is one a browser's IPv4 parser reads as
// a number (the WHATWG URL standard's "ends in a number"): all decimal
// digits, or "0x" or "0X" followed by hex digits, none included.
func numericLabel(label string) bool {
	digits, isHex := label, false
	if len(label) >= 2 && label[0] == '0' && (label[1] == 'x' || label[1] == 'X') {
		digits, isHex = label[2:], true
	}
	for i := 0; i < len(digits); i++ {
		c := digits[i]
		isDigit := c >= '0' && c <= '9'
		if isHex {
			isDigit = isDigit || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F'
		}
		if !isDigit {
			return false
		}
	}
	return true
}

// linkInText reports whether link occurs in text as a whole link: byte for
// byte, preceded by the start of the text or whitespace with only opening
// brackets or quotes between, and followed by the end of the text or
// whitespace with only trailing punctuation between. So a whole link is one
// whitespace-separated word of the text, less the brackets, quotes and
// punctuation around it. A link written with a sentence's full stop after it
// ("see https://a.example.") or in brackets ("(https://a.example)") is found,
// and one that is a prefix of a longer link ("https://a.example.evil.example",
// "https://a.example/@evil") or embedded in one ("https://evil.example/?u=
// https://a.example", "https://evil.example/(https://a.example)") is not. Any
// one occurrence that qualifies is enough.
func linkInText(text, link string) bool {
	if link == "" {
		return false
	}
	for from := 0; from <= len(text)-len(link); {
		i := strings.Index(text[from:], link)
		if i < 0 {
			return false
		}
		start := from + i
		end := start + len(link)
		if linkStartsAt(text[:start]) && linkEndsAt(text[end:]) {
			return true
		}
		from = start + 1
	}
	return false
}

// linkStartsAt reports whether a link may start right after before: at the
// start of the text or after whitespace, with any run of opening brackets or
// quotes between allowed, since a link in brackets or quotes is written with
// them against it. An opener is not a boundary on its own: one inside a word,
// as in "https://evil.example/(https://a.example)", is part of that word.
func linkStartsAt(before string) bool {
	rest := strings.TrimRight(before, linkOpeners)
	if rest == "" {
		return true
	}
	r, _ := utf8.DecodeLastRuneInString(rest)
	return unicode.IsSpace(r)
}

// linkEndsAt reports whether a link may end right before after: at the end of
// the text, or before whitespace, with any run of trailing punctuation
// between allowed, since a link at the end of a sentence or in brackets is
// written with the punctuation against it.
func linkEndsAt(after string) bool {
	rest := strings.TrimLeft(after, linkTrailers)
	if rest == "" {
		return true
	}
	r, _ := utf8.DecodeRuneInString(rest)
	return unicode.IsSpace(r)
}

// linkOpeners are the characters a link may follow directly, besides
// whitespace; linkTrailers the ones that may follow a link directly, as
// punctuation of the text around it rather than part of it. Both are the
// proto's lists (see LinkPreview.url).
const (
	linkOpeners  = `([{<"'`
	linkTrailers = `.,;:!?)]}>"'`
)

// visibleText reports whether s is text a preview may show: something visible
// in it, at least one character that is neither whitespace nor an invisible
// format character (Cf, such as a zero-width space), and no control
// characters beyond a line break. It also refuses the bidirectional
// embedding, override and isolate controls (U+202A–U+202E, U+2066–U+2069),
// which can reorder how text near the title reads, the host a client shows
// beside it included; the bidi marks (U+200E, U+200F, U+061C), common in
// right-to-left text and open nothing, are allowed. This is stricter than a
// group description or a bio (see chat.ValidateDescription) because a preview
// sits beside the host the recipient is asked to trust. Length is the
// proto's to bound. Nothing is normalized: surrounding whitespace is the
// sender's.
func visibleText(s string) bool {
	visible := false
	for _, r := range s {
		switch {
		case r == '\n':
		case unicode.IsControl(r), bidiFormattingControl(r):
			return false
		case !unicode.IsSpace(r) && !unicode.Is(unicode.Cf, r):
			visible = true
		}
	}
	return visible
}

// singleLine reports whether s holds no line break: no line feed (the one
// control visibleText allows) and no line or paragraph separator (U+2028,
// U+2029). A title is one line so that it cannot draw a line of its own
// beneath it that reads as the host ("Your account is locked\nbank.example"),
// beside the true host the client shows; a page's title has no line breaks
// worth keeping. A description may have them.
func singleLine(s string) bool {
	return !strings.ContainsAny(s, "\n\u2028\u2029")
}

// bidiFormattingControl reports whether r opens or closes a bidirectional
// embedding, override or isolate: the Bidi_Control characters other than the
// marks.
func bidiFormattingControl(r rune) bool {
	return r >= '\u202A' && r <= '\u202E' || r >= '\u2066' && r <= '\u2069'
}
